"""Tests for tasks_api.models — Task, Tag, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str_enum(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_sorts_first(self):
        keys = [TaskPriority.order_key(p) for p in (TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW)]
        assert keys == sorted(keys)

    def test_is_str_enum(self):
        assert isinstance(TaskPriority.LOW, str)


class TestTag:
    @pytest.mark.parametrize(
        "raw, expected",
        [
            ("Work", "work"),
            ("  URGENT ", "urgent"),
            ("my-tag_1", "my-tag_1"),
        ],
    )
    def test_normalization(self, raw, expected):
        assert Tag(raw).name == expected

    def test_empty_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_max_length_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_character_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]


class TestTask:
    def test_defaults(self):
        task = Task(id=1, title="Buy milk")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []
        assert task.created_at is not None

    def test_is_overdue_no_due_date(self):
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(now) is False

    def test_is_overdue_done_task(self):
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        past = datetime(2025, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", status=TaskStatus.DONE, due_at=past)
        assert task.is_overdue(now) is False

    def test_is_overdue_true(self):
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        past = datetime(2025, 5, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=past)
        assert task.is_overdue(now) is True

    def test_is_overdue_future_due(self):
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        future = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=future)
        assert task.is_overdue(now) is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

from .conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        items = list(repo.list())
        assert len(items) == 2

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_update_existing(self, repo):
        task = make_task(id=1, title="old")
        repo.add(task)
        task.title = "new"
        repo.update(task)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("work"), Tag("WORK"), Tag("Work")])
        assert [t.name for t in result] == ["work"]

    def test_preserves_order(self):
        result = normalize_tags(["beta", "alpha", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

    def test_converts_strings(self):
        result = normalize_tags(["Hello", "World"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_empty(self):
        assert normalize_tags([]) == []

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("foo"), "FOO", "bar"])
        assert [t.name for t in result] == ["foo", "bar"]

